import numpy as np
def objects(g):
    g=np.array(g); seen=np.zeros_like(g,bool); objs=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j] and not seen[i,j]:
                c=g[i,j]; stack=[(i,j)]; seen[i,j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<g.shape[0] and 0<=nx<g.shape[1] and g[ny,nx]==c and not seen[ny,nx]:
                            seen[ny,nx]=True; stack.append((ny,nx))
                objs.append(cells)
    return objs

def has_hole(g,cells):
    g=np.array(g); ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    # flood fill zeros from border of bbox in full grid; holes = zeros inside bbox not reachable
    sub=g[y0:y1+1,x0:x1+1]
    H,W=sub.shape; vis=np.zeros_like(sub,bool); st=[]
    for i in range(H):
        for j in range(W):
            if (i in(0,H-1) or j in(0,W-1)) and sub[i,j]==0: vis[i,j]=True; st.append((i,j))
    while st:
        y,x=st.pop()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and sub[ny,nx]==0 and not vis[ny,nx]:
                vis[ny,nx]=True; st.append((ny,nx))
    return any(sub[i,j]==0 and not vis[i,j] for i in range(H) for j in range(W))

def transform(g):
    g=np.array(g); H,W=g.shape
    out=np.zeros_like(g)
    hollow=[]; plus=[]
    for cells in objects(g):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        y0,x0=min(ys),min(xs); h=max(ys)-y0+1; w=max(xs)-x0+1
        shape=[[(g[y0+dy,x0+dx] if (y0+dy,x0+dx) in cells else 0) for dx in range(w)] for dy in range(h)]
        (hollow if has_hole(g,cells) else plus).append((min(ys),y0,x0,shape))
    placed=[]
    def fits(r0,c0,shape):
        for i,row in enumerate(shape):
            for j,v in enumerate(row):
                if v and (r0+i>=H or out[r0+i,c0+j]!=0): return False
        return True
    for _,y0,x0,shape in sorted(hollow):
        r=0
        while not fits(r,x0,shape): r+=1
        for i,row in enumerate(shape):
            for j,v in enumerate(row):
                if v: out[r+i,x0+j]=v
    for _,y0,x0,shape in sorted(plus):
        r=H-len(shape)
        while r>=0 and not fits(r,x0,shape): r-=1
        for i,row in enumerate(shape):
            for j,v in enumerate(row):
                if v: out[r+i,x0+j]=v
    return out.tolist()

